533	     */
534	    public final Object deserialize(JsonParser p, DeserializationContext ctxt) throws IOException
535	    {
536	        if (p.hasToken(JsonToken.VALUE_NULL)) {
537	            return _nullProvider.getNullValue(ctxt);
538	        }
539	        if (_valueTypeDeserializer != null) {
540	            return _valueDeserializer.deserializeWithType(p, ctxt, _valueTypeDeserializer);
541	        }
