550	    /**
551	     * @since 2.9
552	     */
553	    public final Object deserializeWith(JsonParser p, DeserializationContext ctxt,
554	            Object toUpdate) throws IOException
555	    {
556	        // 20-Oct-2016, tatu: Not 100% sure what to do; probably best to simply return
557	        //   null value and let caller decide what to do.
558	        if (p.hasToken(JsonToken.VALUE_NULL)) {
559	            // ... except for "skip nulls" case which should just do that:
560	            if (NullsConstantProvider.isSkipper(_nullProvider)) {
561	                return toUpdate;
562	            }
563	            return _nullProvider.getNullValue(ctxt);
564	        }
565	        if (_valueTypeDeserializer != null) {
566	            // 25-Oct-2021 Added by James to support merging polymorphic property
567	            // https://github.com/FasterXML/jackson-databind/issues/2541
568	            // Please note we only support merging same type polymorphic property for now,
569	            // merging different type is hard and usually doesn't make sense.
570	            // Please note you need to configure {@link DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES} as false to
571	            // enable this feature otherwise the unknown property exception will be thrown.
572	            JavaType subType = ctxt.getTypeFactory().constructType(toUpdate.getClass());
573	            JsonDeserializer<Object> subTypeValueDeserializer = ctxt.findContextualValueDeserializer(subType, this);
574	            return subTypeValueDeserializer.deserialize(p, ctxt, toUpdate);
575	        }
576	        // 04-May-2018, tatu: [databind#2023] Coercion from String (mostly) can give null
577	        Object value = _valueDeserializer.deserialize(p, ctxt, toUpdate);
578	        if (value == null) {
579	            if (NullsConstantProvider.isSkipper(_nullProvider)) {
580	                return toUpdate;
581	            }
582	            value = _nullProvider.getNullValue(ctxt);
583	        }
584	        return value;
585	    }
