596	     */
597	    protected void _throwAsIOE(JsonParser p, Exception e, Object value) throws IOException
598	    {
599	        if (e instanceof IllegalArgumentException) {
600	            String actType = ClassUtil.classNameOf(value);
601	            StringBuilder msg = new StringBuilder("Problem deserializing property '")
602	                    .append(getName())
603	                    .append("' (expected type: ")
604	                    .append(getType())
605	                    .append("; actual type: ")
606	                    .append(actType).append(")");
607	            String origMsg = ClassUtil.exceptionMessage(e);
608	            if (origMsg != null) {
609	                msg.append(", problem: ")
610	                    .append(origMsg);
611	            } else {
612	                msg.append(" (no error message provided)");
613	            }
614	            throw JsonMappingException.from(p, msg.toString(), e);
615	        }
616	        _throwAsIOE(p, e);
617	    }
